const GLOBE = `const c=document.getElementById('globe');if(c){const x=c.getContext('2d'),d=devicePixelRatio||1,R=c.clientWidth;c.width=R*d;c.height=R*d;const P=[];for(let i=0;i<700;i++){const a=Math.acos(1-2*(i+.5)/700),b=Math.PI*(1+5**.5)*i;P.push([Math.sin(a)*Math.cos(b),Math.cos(a),Math.sin(a)*Math.sin(b)])}const pins=[[.3,.2],[1.6,.5],[2.9,-.3],[4.2,.6],[5.3,-.1]];(function f(t){x.clearRect(0,0,c.width,c.height);const r=c.width*.42,cx=c.width/2,cy=c.height/2,th=t/6000;for(const[p0,p1,p2]of P){const X=p0*Math.cos(th)-p2*Math.sin(th),Z=p0*Math.sin(th)+p2*Math.cos(th);x.fillStyle='rgba(125,167,255,'+(.15+.55*(Z+1)/2)+')';x.fillRect(cx+X*r,cy-p1*r,d*1.4,d*1.4)}for(const[lo,la]of pins){const X0=Math.cos(la)*Math.cos(lo+th*0),Z0=Math.cos(la)*Math.sin(lo);const X=X0*Math.cos(th)-Z0*Math.sin(th),Z=X0*Math.sin(th)+Z0*Math.cos(th);if(Z>0){const k=(Math.sin(t/400+lo)+1)/2;x.strokeStyle='rgba(91,228,155,'+(.9-.6*k)+')';x.beginPath();x.arc(cx+X*r,cy-Math.sin(la)*r,d*(3+8*k),0,6.3);x.stroke();x.fillStyle='#5BE49B';x.beginPath();x.arc(cx+X*r,cy-Math.sin(la)*r,d*3,0,6.3);x.fill()}}requestAnimationFrame(f)})(0)}`;
const LIVEF = `var src='',fp=document.getElementById('fp'),ft=document.getElementById('ft');function ap(){var t=Number(ft.value),now=Date.now();document.querySelectorAll('[data-m]').forEach(function(e){var ok=(!src||e.dataset.s===src)&&(!fp.value||e.dataset.p===fp.value)&&(!t||now-Number(e.dataset.at)<=t);if(!ok)e.style.display='none';else{e.style.display='';if(src||fp.value||t)e.hidden=false}})}document.querySelectorAll('[data-src]').forEach(function(b){b.onclick=function(){src=b.dataset.src;document.querySelectorAll('[data-src]').forEach(function(x){x.classList.toggle('on',x===b)});ap()}});fp.onchange=ap;ft.onchange=ap`;
const FILTER = `const q=document.getElementById('q'),rows=[...document.querySelectorAll('.row[data-t]')];let cat='';function ap(){const v=(q.value||'').toLowerCase();for(const r of rows){if(v||cat)r.hidden=false;r.style.display=(!v||r.dataset.t.includes(v))&&(!cat||r.dataset.c.split(',').includes(cat))?'':'none'}}q.oninput=ap;document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{cat=b.dataset.cat;document.querySelectorAll('[data-cat]').forEach(x=>x.classList.toggle('on',x===b));ap()})`;

const TONES = ['#1D4ED8', '#7C3AED', '#B45309', '#0F766E', '#BE185D', '#334155'];
const toneOf = (slug) => TONES[[...String(slug)].reduce((a, c) => a + c.charCodeAt(0), 0) % TONES.length];
const OWNER = /^[A-Za-z0-9](?:[A-Za-z0-9-]{0,38})$/;
// The letter tile is always drawn; the GitHub owner avatar sits on top and removes itself if it fails to load.
export const mark = (r, n = 44) => {
  const owner = String(r.repo || '').split('/')[0];
  const img = OWNER.test(owner) ? `<img src="https://github.com/${esc(owner)}.png?size=${n * 2}" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.remove()" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover">` : '';
  return `<span class="mk" aria-hidden="true" style="position:relative;overflow:hidden;width:${n}px;height:${n}px;background:${toneOf(r.slug)};font-size:${Math.round(n * .42)}px">${esc((r.name || '?')[0].toUpperCase())}${img}</span>`;
};

export function userBox(who) {
  return who ? `<a class="me" href="/logout" title="Sign out">${esc(who)} &middot; signed in</a>` : '<a class="cta" href="/login">Sign in with GitHub</a>';
}

export function shell(title, body, { desc = 'Flisk Ranker ranks products by what happened on GitHub and gives each one a live README badge.', script = '' } = {}) {
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><meta name="description" content="${esc(desc)}"><link rel="icon" href="/icon.svg"><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Inter:wght@200;300;400;500;600&family=Geist+Mono:wght@400;500&display=swap" rel="stylesheet"><style>${CSS}</style></head><body><div class="w"><nav><a class="l" href="/">&gt;_ flisk.ranker</a><a href="/">Trending</a><a href="/#all">Products</a><a href="/compare">Compare</a><a href="/live">Live mentions</a><a href="/badges">Badges</a><a href="/submit">Submit</a><span class="s"></span><a href="https://flisk.si" rel="noopener">All Flisk products</a><!--USER--></nav>${body}</div>${script ? `<script>${script}</script>` : ''}</body></html>`;
}

const PER = [['daily', 'Today'], ['weekly', 'This week'], ['monthly', 'This month'], ['yearly', 'This year']];
const PLAB = { daily: 'STARS TODAY', weekly: 'STARS THIS WEEK', monthly: 'STARS THIS MONTH', yearly: 'STARS THIS YEAR' };

function line(vals, w = 120, h = 34, color = '#5BE49B') {
  if (!vals || vals.length < 2) return '';
  const lo = Math.min(...vals), hi = Math.max(...vals), span = hi - lo || 1;
  const pts = vals.map((v, i) => `${Math.round((i / (vals.length - 1)) * w)},${Math.round(h - 2 - ((v - lo) / span) * (h - 4))}`).join(' ');
  return `<svg viewBox="0 0 ${w} ${h}" width="${w}" height="${h}" aria-hidden="true"><polyline points="${pts}" fill="none" stroke="${color}" stroke-width="1.6"/></svg>`;
}
const starsOf = (snaps, slug, n = 30) => snaps.filter((x) => x.slug === slug).sort((a, b) => (a.day < b.day ? -1 : 1)).slice(-n).map((x) => x.stars);

export function home(rows, period, snaps = [], ments = []) {
  const by = (slug) => ments.filter((m) => m.slug === slug);
  const stars = rows.reduce((a, r) => a + r.stars, 0), gain = rows.reduce((a, r) => a + Math.max(0, r.gain), 0), ver = rows.filter((r) => r.verified).length;
  const tabs = PER.map(([k, l]) => `<a href="/?period=${k}" class="pill ${k === period ? 'on' : ''}">${l}</a>`).join(' ');
  const list = rows.length
    ? rows.slice(0, 100).map((r, i) => `<div class="row"${i >= 50 ? ' hidden data-more="1"' : ''} data-t="${esc((r.name + ' ' + r.tagline + ' ' + r.repo).toLowerCase())}" data-c="${esc(r.topics || '')}"><span class="n">${r.rank}</span>${mark(r)}<div class="m"><b><a href="/p/${esc(r.slug)}">${esc(r.name)}</a></b> <span class="pill">Repo</span>${r.verified ? ' <span class="pill ok">&#10003; VERIFIED</span>' : ''}${r.isNew ? ' <span class="pill">NEW</span>' : ''}<p>${esc(r.tagline)}</p><div style="margin-top:6px"><span class="lbl">MENTIONED ON</span> ${[...new Set(by(r.slug).map((m) => SRC[m.source] || m.source))].map((x) => `<span class="pill">${esc(x)}</span>`).join(' ') || '<span class="pill">none yet</span>'} ${[r.license, r.language].filter(Boolean).map((x) => `<span class="pill">${esc(x)}</span>`).join(' ')} <span class="pill">&#9733; ${short(r.stars)}</span> <span class="pill">&#9095; ${short(r.forks || 0)}</span> <span class="pill soon">Price: coming soon</span> <a class="pill" href="/compare?p=${esc(r.slug)}">Compare</a></div></div>${line(starsOf(snaps, r.slug))}<div class="g">${gainTxt(r)}<small>${r.isNew ? 'first day' : PLAB[period]}</small></div></div>`).join('')
    : '<p class="sub" style="padding:24px 0">No products yet. <a href="/submit" style="text-decoration:underline">Be the first</a>.</p>';
  const sample = rows[0]?.slug || 'sample';
  const cats = [...new Set(rows.flatMap((r) => String(r.topics || '').split(',').filter(Boolean)))].slice(0, 12);
  const tick = ments.slice(0, 8).map((m) => `<span style="white-space:nowrap">${esc(SRC[m.source] || m.source)} &middot; ${esc(m.who || '')} &middot; ${esc((rows.find((r) => r.slug === m.slug) || {}).name || m.slug)}</span>`).join('<span style="opacity:.4"> &nbsp;/&nbsp; </span>');
  const body = `${tick ? `<div class="mono" style="display:flex;gap:6px;overflow:hidden;font-size:12px;color:#9AA0AA;padding:8px 0;border-bottom:1px solid #1d2128" aria-label="Latest mentions">${tick}</div>` : ''}<div class="hero"><div class="t"><div class="lbl">FLISK RANKER &middot; RANKED BY STARS GAINED</div><h1>Where products rise.</h1><p class="sub">Every product on GitHub, ranked the same way for everyone. Submit yours, wear the live badge in your README.</p><div class="srch"><input id="q" placeholder="Search products" aria-label="Search products"><a class="pill on" href="/">Trending</a><a class="pill" href="/compare">Compare</a><a class="pill" href="/badges">Badges</a><span class="pill soon">Ask AI: coming soon</span></div><p style="margin-top:22px"><a class="btn p" href="/submit" style="padding:12px 20px">Submit your product, free</a> <a class="btn" href="/badges" style="padding:12px 20px">How the badge works</a></p></div><canvas id="globe" aria-hidden="true"></canvas></div>
<div class="stats"><div><b>${rows.length}</b><span class="lbl">Products listed</span></div><div><b>${short(stars)}</b><span class="lbl">Stars in total</span></div><div><b>+${short(gain)}</b><span class="lbl">${PLAB[period].toLowerCase()}</span></div><div><b>${ver}</b><span class="lbl">Verified by makers</span></div></div>
<div class="cols" id="all"><div class="a"><div style="display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-bottom:12px"><span class="lbl">LIVE TRENDING &middot; RISING RIGHT NOW</span><span style="flex:1"></span>${tabs}</div>${cats.length ? `<div style="display:flex;flex-wrap:wrap;gap:8px;margin-bottom:8px"><button type="button" class="pill on" data-cat="">All</button>${cats.map((c) => `<button type="button" class="pill" data-cat="${esc(c)}">${esc(c)}</button>`).join('')}</div>` : ''}${list}${rows.length > 50 ? `<p style="margin-top:16px"><button type="button" class="btn" onclick="document.querySelectorAll('[data-more]').forEach(function(e){e.hidden=false});this.remove()">Show the next ${Math.min(50, rows.length - 50)} &#8594;</button></p>` : ''}</div>
<div class="b"><div class="card"><div class="lbl">YOUR BADGE</div><p style="margin:12px 0"><img src="/badge/${esc(sample)}.svg" width="250" height="55" alt="Badge"></p><a class="btn" href="/badges">See all badges</a></div>
<div class="card"><div class="lbl">LIVE MENTIONS</div>${ments.slice(0, 4).map((m) => mrow(m, rows.find((r) => r.slug === m.slug))).join('') || '<p style="margin:10px 0 14px;font-size:14px;color:#9AA0AA">No mentions yet. We look every hour.</p>'}<p style="margin-top:14px"><a class="btn" href="/live">Open live mentions</a></p></div>
<div class="card blue"><div class="lbl">FOR MAKERS</div><p style="margin:10px 0 14px;font-size:14px;color:#B8BDC6">Paste one link. We read GitHub every day and give you a live badge. Nobody can buy a rank.</p><a class="btn p" href="/submit">Claim your page</a></div><div class="spon"><div class="lbl">FEATURED &middot; SPONSOR SLOT</div><p style="margin:8px 0 0">Marked and kept apart from the list. Paying never changes a rank.</p></div></div></div>`;
  return shell('Flisk Ranker', body, { script: GLOBE + ';' + FILTER });
}

export function embedBox(origin, slug, language = '') {
  const L = embed(origin, slug), S = embed(origin, slug, { size: 'small' }), G = embed(origin, slug, { scope: 'language' });
  const lang = language ? `<div class="lbl" style="margin-top:14px">Rank in ${esc(language)} only</div><p style="margin:8px 0"><img src="${esc(G.url)}" width="250" height="55" alt=""></p><code>${esc(G.markdown)}</code>` : '';
  return `<div class="card"><div class="lbl">COPY THIS INTO YOUR README</div><code id="md">${esc(L.markdown)}</code><div class="lbl" style="margin-top:14px">Small, 20 px</div><code>${esc(S.markdown)}</code>${lang}<div class="lbl" style="margin-top:14px">HTML</div><code>${esc(L.html)}</code><button type="button" onclick="navigator.clipboard.writeText(document.getElementById('md').textContent);this.textContent='Copied'">Copy</button></div>`;
}

function momentum(snaps, slug) {
  const s = snaps.filter((x) => x.slug === slug).sort((a, b) => (a.day < b.day ? -1 : 1)).slice(-90);
  if (s.length < 2) return '<p style="color:#8A8F98;font-size:14px;margin:10px 0 0">The chart fills in as we read GitHub each day. Check back tomorrow.</p>';
  const v = s.map((x) => x.stars), lo = Math.min(...v), hi = Math.max(...v), span = hi - lo || 1, W = 800, H = 160;
  const pts = v.map((y, i) => `${Math.round((i / (v.length - 1)) * W)},${Math.round(H - 8 - ((y - lo) / span) * (H - 16))}`);
  return `<svg viewBox="0 0 ${W} ${H}" style="width:100%;height:auto;margin-top:12px" preserveAspectRatio="none" aria-label="Stars, last ${s.length} days"><polygon points="0,${H} ${pts.join(' ')} ${W},${H}" fill="rgba(60,120,255,.18)"/><polyline points="${pts.join(' ')}" fill="none" stroke="#7DA7FF" stroke-width="2"/></svg><div class="lbl" style="display:flex;justify-content:space-between;margin-top:6px"><span>${esc(s[0].day)} &middot; ${short(lo)}</span><span>${esc(s[s.length - 1].day)} &middot; ${short(hi)}</span></div>`;
}

function heat(snaps, slug) {
  const v = snaps.filter((x) => x.slug === slug).sort((a, b) => (a.day < b.day ? -1 : 1));
  const g = v.map((x, i) => (i ? Math.max(0, x.stars - v[i - 1].stars) : 0)).slice(-84);
  while (g.length < 84) g.unshift(0);
  const m = Math.max(1, ...g);
  return `<div class="heat" style="margin-top:14px">${g.map((n) => `<i style="background:${n ? `rgba(91,228,155,${(.25 + .75 * n / m).toFixed(2)})` : '#12151A'}"></i>`).join('')}</div>`;
}
function achv(p, row) {
  const a = [], st = row?.stars || 0;
  if (p.verified) a.push('Verified by the maker');
  if (row && row.rank <= 10) a.push('Top 10 today');
  if (row && row.rank === 1) a.push('Product of the day');
  for (const n of [100, 1000, 10000, 100000]) if (st >= n) a.push(short(n) + ' stars');
  return a;
}

export function product(p, row, origin, snaps = [], all = [], ranks = {}, ments = [], fx = null) {
  const rank = row?.rank || 0, stars = row?.stars || 0;
  const alts = all.filter((r) => r.slug !== p.slug).sort((a, b) => (b.language === p.language) - (a.language === p.language)).slice(0, 4);
  const body = `<div style="padding:24px 0 8px"><span class="lbl"><a href="/">TRENDING</a> / ${esc(p.repo)}</span></div>
<div style="display:flex;flex-wrap:wrap;gap:22px;align-items:center;padding:12px 0 24px">${mark(p, 92)}<div style="flex:1 1 380px;min-width:0"><div style="display:flex;flex-wrap:wrap;gap:10px;align-items:center"><h1 style="margin:0;font-size:clamp(30px,5vw,48px)">${esc(p.name)}</h1><span class="pill">Repo</span>${p.verified ? '<span class="pill ok">&#10003; VERIFIED BY THE MAKER</span>' : ''}</div><p class="sub" style="margin-top:8px">${esc(p.tagline)}</p><div style="margin-top:12px">${[p.license, p.language].filter(Boolean).map((x) => `<span class="pill">${esc(x)}</span>`).join(' ')} ${(p.topics || '').split(',').filter(Boolean).slice(0, 3).map((t) => `<a class="pill" href="/#all">${esc(t)}</a>`).join(' ') || '<span class="pill soon">Category: none set on GitHub</span>'} ${fx?.last ? `<span class="pill">${esc(fx.last.tag)} &middot; ${ago(fx.last.at)}</span>` : '<span class="pill soon">Release: none found</span>'}</div><p style="margin-top:14px">${p.homepage ? `<a class="btn p" href="${esc(p.homepage)}" rel="nofollow">Visit</a> ` : ''}<a class="btn" href="https://github.com/${esc(p.repo)}" rel="nofollow">View on GitHub</a> <a class="btn" href="/compare?p=${esc(p.slug)}">Compare</a></p>${(() => { const bits = []; if (ranks.prev && rank && ranks.prev !== rank) bits.push(`<span class="pill ${ranks.prev > rank ? 'ok' : ''}">${ranks.prev > rank ? 'UP' : 'DOWN'} ${Math.abs(ranks.prev - rank)} PLACE${Math.abs(ranks.prev - rank) > 1 ? 'S' : ''} SINCE YESTERDAY</span>`); if (ranks.cat) bits.push(`<span class="pill">#${ranks.cat.rank} of ${ranks.cat.of} in ${esc(ranks.cat.topic)} this month</span>`); return bits.length ? `<p style="margin-top:10px">${bits.join(' ')}</p>` : ''; })()}</div></div>
<div class="stats">${[['daily', 'today'], ['weekly', 'this week'], ['monthly', 'this month'], ['yearly', 'this year']].map(([k, l]) => `<div><b>${ranks[k] ? '#' + ranks[k] : '-'}</b><span class="lbl">Rank ${l}</span></div>`).join('')}</div>
<div class="stats" style="border-top:0"><div><b>${short(stars)}</b><span class="lbl">Stars</span></div><div><b>${short(row?.forks || 0)}</b><span class="lbl">Forks</span></div><div><b>${row ? gainTxt(row) : '-'}</b><span class="lbl">Stars today</span></div><div><b>${fx?.prs ?? SOON}</b><span class="lbl">Merged PRs, 30 days</span></div><div><b>${ments.length}</b><span class="lbl">Mentions, 30 days</span></div></div>
<div class="cols"><div class="a"><div class="card"><div style="display:flex;flex-wrap:wrap;gap:10px;align-items:center"><div class="lbl">MOMENTUM &middot; STARS, LAST 90 DAYS</div><span style="flex:1"></span>${['90d', '30d', '7d', 'All'].map((n, i) => `<span class="pill ${i ? 'soon' : 'on'}">${n}</span>`).join('')}</div>${momentum(snaps, p.slug)}</div>
<div class="card" style="margin-top:20px"><div class="lbl">LAST 30 DAYS &middot; GIT STATS</div><div style="display:flex;flex-wrap:wrap;gap:28px;margin:18px 0 4px">${[['COMMITS', fx?.commits30], ['CONTRIBUTORS', fx?.contributors30 == null ? null : (fx.contributorsMore ? fx.contributors30 + '+' : fx.contributors30)], ['PRS OPENED', fx?.prsOpened], ['PRS MERGED', fx?.prs], ['ISSUES OPENED', fx?.issuesOpened], ['ISSUES CLOSED', fx?.issues]].map(([l, v]) => `<div style="flex:1 1 130px"><div style="font-size:20px">${v == null ? SOON : typeof v === 'number' ? short(v) : v}</div><div class="lbl" style="margin-top:8px">${l}</div></div>`).join('')}</div></div>
<div class="card" style="margin-top:20px"><div class="lbl">GITHUB ACTIVITY &middot; LAST 12 WEEKS</div><div style="display:flex;flex-wrap:wrap;gap:28px;margin:18px 0">${[['COMMITS', fx?.commits ? fx.commits.reduce((a, b) => a + b, 0) : null], ['MERGED PRS', fx?.prs ?? null], ['ISSUES CLOSED', fx?.issues ?? null], ['RELEASES', fx?.releases ?? null]].map(([l, v]) => `<div style="flex:1 1 130px"><div style="font-size:20px">${v ?? SOON}</div><div class="lbl" style="margin-top:8px">${l}</div></div></div>`).join('')}</div><div class="lbl" style="margin-bottom:10px">STARS GAINED PER DAY, LAST 84 DAYS</div>${heat(snaps, p.slug)}</div>
<div class="card" style="margin-top:20px"><div class="lbl">PRICES</div><p style="margin:10px 0 0;font-size:14px;color:#9AA0AA">${SOON} ${p.license ? esc(p.license) + ' licence.' : ''}</p></div>
<div class="card" style="margin-top:20px"><div style="display:flex;flex-wrap:wrap;gap:10px;align-items:center"><span class="lbl">WHERE IT WAS MENTIONED</span><span style="flex:1"></span><span class="mono" style="font-size:11px;color:#8A8F98">via Flisk Grow &middot; ${ments.length} in 30 days &middot; X, Reddit, YouTube: coming soon</span></div>${ments.slice(0, 8).map((m) => mrow(m)).join('') || '<p style="margin:12px 0 0;font-size:14px;color:#9AA0AA">No mentions found yet on Hacker News or Bluesky. We look every hour.</p>'}</div></div>
<div class="b"><div class="card"><div class="lbl">YOUR BADGE, LIVE</div><p style="margin:14px 0 8px"><img src="/badge/${esc(p.slug)}.svg" width="250" height="55" alt="Flisk Ranker badge"></p><img src="/badge/${esc(p.slug)}.svg?size=small" height="20" alt="Small badge"><p style="font-size:13px;color:#9AA0AA;margin:12px 0">${rank ? `#${rank} today, ${RANKS[rankOf(rank)]}. ${BODIES[bodyOf(stars)]} with ${short(stars)} stars.` : 'Not ranked yet.'}</p>${p.verified ? '<span class="ok">Verified: the badge is in the README.</span>' : '<small>Not verified yet. Put the badge in your README, then press the button.</small><br><br><button id="v">Check my README</button> <small id="vm"></small>'}</div>${embedBox(origin, p.slug, p.language)}
<div class="card"><div class="lbl">ACHIEVEMENTS</div><div style="display:flex;flex-wrap:wrap;gap:8px;margin-top:12px">${achv(p, row).map((a) => `<span class="pill ok">${esc(a)}</span>`).join('') || '<small>None yet. They come with stars and rank.</small>'}</div></div>${alts.length ? `<div class="card"><div class="lbl">ALTERNATIVES</div>${alts.map((r) => `<div style="display:flex;gap:10px;align-items:center;padding-top:12px">${mark(r, 30)}<a href="/p/${esc(r.slug)}">${esc(r.name)}</a><span style="flex:1"></span><span class="lbl">${short(r.stars)} &#9733;</span></div>`).join('')}</div>` : ''}</div></div>`;
  const script = p.verified ? '' : `document.getElementById('v').onclick=async()=>{const m=document.getElementById('vm');m.textContent='Checking...';const r=await fetch('/api/verify/${esc(p.slug)}',{method:'POST'}).then(r=>r.json()).catch(()=>({}));m.textContent=r.verified?'Verified.':'Badge not found in the README yet.';if(r.verified)location.reload()}`;
  return shell(`${p.name} on Flisk Ranker`, body, { desc: p.tagline || undefined, script });
}

export function submit(who = '') {
  const script = `var E=function(t){return String(t==null?'':t).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]})};var f=document.getElementById('f'),W=document.getElementById('wiz'),t0=0;f.onsubmit=async function(e){e.preventDefault();var m=document.getElementById('m');m.textContent='Importing...';t0=Date.now();var r=await fetch('/api/submit',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({url:document.getElementById('u').value})}).then(function(r){return r.json()}).catch(function(){return {error:'No answer. Try again.'}});if(!r.slug){m.textContent=r.error||'Something went wrong.';return}m.textContent='';var p=r.product,secs=Math.max(1,Math.round((Date.now()-t0)/1000));var md='[![Flisk Ranker]('+location.origin+'/badge/'+r.slug+'.svg)]('+location.origin+'/p/'+r.slug+')';W.hidden=false;W.innerHTML='<div class="card live"><div class="lbl ok">&#10003; IMPORTED IN '+secs+' SECOND'+(secs>1?'S':'')+'</div><p class="mono" style="font-size:11px;color:#6B7079;margin:6px 0 0">Everything came from the link.</p><div style="display:flex;gap:16px;align-items:center;margin:16px 0 0"><div><b style="font-size:20px">'+E(p.name)+'</b> <span class="pill">Repo</span><p style="margin:6px 0 0;color:#B8BDC6;font-size:14px">'+E(p.tagline)+'</p><p style="margin:10px 0 0">'+[p.license,p.language].concat((p.topics||'').split(',').slice(0,2)).filter(Boolean).map(function(x){return \'<span class="pill">\'+E(x)+\'</span> \'}).join('')+\'<span class="pill">&#9733; \'+p.stars.toLocaleString()+\'</span></p></div></div><div class="lbl" style="margin-top:18px">WE WILL LOOK FOR MENTIONS OF</div><p style="margin:8px 0 0">'+r.terms.map(function(x){return \'<span class="pill">\'+E(x)+\'</span> \'}).join('')+'</p><p style="margin:18px 0 0"><button id="go">Looks right, continue</button></p></div><div id="s3" class="card" hidden style="margin-top:20px"><div class="lbl">STEP 3 &middot; ADD THE BADGE TO PROVE IT IS YOURS</div><p style="margin:12px 0;font-size:14px;color:#B8BDC6">Paste this in your README. When we find it there, your page turns <span class="ok">verified</span> and the badge starts showing your live rank.</p><img src="/badge/'+r.slug+'.svg" width="250" height="55" alt=""><pre class="code" id="md" style="margin:12px 0;white-space:pre-wrap;word-break:break-all">'+E(md)+'</pre><p><button id="cp">Copy</button> <button id="ck">Check my README now</button> <small id="cm">We also check once a day.</small></p></div><div id="s4" class="card live" hidden style="margin-top:20px"><div class="lbl ok">STEP 4 &middot; YOU ARE LIVE</div><p id="s4t" style="margin:10px 0 0;font-size:14px;color:#B8BDC6"></p><p style="margin:14px 0 0"><a class="btn p" href="'+r.url+'">Open my page</a> <a class="btn" target="_blank" rel="noopener" href="https://twitter.com/intent/tweet?text='+encodeURIComponent('I just listed '+p.name+' on Flisk Ranker')+'&url='+encodeURIComponent(location.origin+r.url)+'">Share on X</a></p></div>';document.getElementById('go').onclick=function(){document.getElementById('s3').hidden=false;document.getElementById('s4').hidden=false;document.getElementById('s4t').textContent=p.name+' is listed and ranked. Your page: '+location.host+r.url+'. We read GitHub every day and search for mentions every hour.';document.getElementById('s3').scrollIntoView({behavior:'smooth'})};W.addEventListener('click',function(ev){if(ev.target.id==='cp'){navigator.clipboard&&navigator.clipboard.writeText(md);ev.target.textContent='Copied'}if(ev.target.id==='ck'){var c=document.getElementById('cm');c.textContent='Checking...';fetch('/api/verify/'+r.slug,{method:'POST'}).then(function(x){return x.json()}).then(function(v){c.textContent=v.verified?'Found it. Your page is verified.':'Not found yet. Add the badge to your README and press again.'})}})}`;
  const step = (n, t, c, on) => `<div><div class="mono" style="font-size:12px;color:${c}">${n}</div><div style="font-size:16px;font-weight:400;margin-top:6px;color:${on ? '#fff' : '#8A8F98'}">${t}</div></div>`;
  const body = `<div class="hero"><div class="lbl">SUBMIT YOUR PRODUCT &middot; FREE &middot; TWO MINUTES</div><h1>Get listed, get ranked, wear the badge.</h1><p class="sub">Paste one link. We read GitHub every day and give you a live badge to put in your README.</p></div>
<div class="steps">${step(who ? '01 &middot; DONE' : '01', who ? `Signed in as ${esc(who)}` : 'Sign in with GitHub', who ? '#5BE49B' : '#fff', true)}${step('02 &middot; NOW', 'Paste one link', '#fff', true)}${step('03', 'Add the badge', '#6B7079', false)}${step('04', 'Go live', '#6B7079', false)}</div>
<div class="cols"><div class="a"><div class="card"><div class="lbl">STEP 2 &middot; PASTE ONE LINK. WE DO THE REST.</div><div style="display:flex;flex-wrap:wrap;gap:8px;margin-top:16px"><span class="pill on">GitHub</span><span class="pill on">Website</span><span class="pill on">npm / PyPI</span>${['Product Hunt', 'Docker Hub', 'Hugging Face'].map((n) => `<span class="pill soon">${n}: coming soon</span>`).join('')}</div><form id="f" style="margin-top:16px"><input id="u" placeholder="https://github.com/you/your-product or an npm, PyPI or website link" required><p style="margin:14px 0 0"><button>Import</button> <small id="m"></small></p></form><p style="font-size:12px;color:#6B7079;margin:12px 0 0">Works with a GitHub, npm, PyPI or website link that points to a GitHub repo. Name, line, licence, language and stars all come from the link.</p>${who ? '' : '<p style="margin:14px 0 0"><a class="btn" href="/login">Sign in with GitHub</a> <small>to see your products here later</small></p>'}</div>
<div id="wiz" hidden style="margin-top:20px"></div>
<div class="card" style="margin-top:20px"><div class="lbl">STEP 3 &middot; ADD THE BADGE TO PROVE IT IS YOURS</div><p style="margin:12px 0 0;font-size:14px;color:#B8BDC6">After you import, your page shows the line to paste in your README. When we find it there, your page turns <span class="ok">verified</span>.</p><p style="margin:16px 0 0"><img src="/badge/sample.svg" width="250" height="55" alt="Sample badge"></p></div>
<div class="card live" style="margin-top:20px"><div class="lbl ok">STEP 4 &middot; YOU ARE LIVE</div><p style="margin:10px 0 0;font-size:14px;color:#B8BDC6">After the import you land on your page, listed and ranked. Press Check my README there once the badge is in, and it turns verified.</p></div></div>
<div class="b"><div class="card"><div class="lbl">WHAT YOU GET, FREE</div><div class="kv" style="margin-top:14px"><div><i>&#10003;</i>A page with your live rank and star history</div><div><i>&#10003;</i>Stars and forks read every day</div><div><i>&#10003;</i>Rank badges for your README, big and small</div><div><i>&#10003;</i>A spot in compare and alternatives</div></div></div>
<div class="card blue"><div class="lbl">MAKER PLAN</div><p style="margin:10px 0 0;font-size:14px;color:#B8BDC6">Daily email when your rank moves, reply links on mentions, a pinned category spot. ${SOON}</p></div><div class="card"><div class="lbl">HOW THE RANK WORKS</div><p style="margin:10px 0 0;font-size:13px;line-height:1.6;color:#9AA0AA">Stars gained, counted the same way for everyone. Paying never changes a rank.</p></div></div></div>`;
  return shell('Submit your product', body, { script });
}

export function badges(rows, origin) {
  const top = rows[0]?.slug;
  const live = [['Rank today', 'daily', 'Your place in the daily ranking. Changes every day.'], ['Rank this week', 'weekly', 'Your place this week.'], ['Rank this month', 'monthly', 'Your place this month.'], ['Rank this year', 'yearly', 'Your place this year.']];
  const soon = [['Rank in a category', 'Shows when you are in the top 10 of your category.'], ['Verified', 'Appears once we find the badge in your README.'], ['Stars gained', 'Live stars gained, straight from GitHub.'], ['Trending streak', 'Days in a row you stayed in the top 10.'], ['Product of the day', 'For the top product of each day.'], ['Mentions', 'How many times people talked about you.']];
  const gallery = (top ? live.map(([n, per, d]) => `<div class="card" style="flex:1 1 300px"><img src="/badge/${esc(top)}.svg?period=${per}" width="250" height="55" alt=""><div style="font-size:15px;font-weight:500;margin:14px 0 4px">${n}</div><div style="font-size:13px;color:#8A8F98">${d} Add ?period=${per}.</div></div>`).join('') : '') + soon.map(([n, d]) => `<div class="card" style="flex:1 1 300px"><div style="height:55px;display:flex;align-items:center"><span class="pill soon">Coming soon</span></div><div style="font-size:15px;font-weight:500;margin:14px 0 4px">${n}</div><div style="font-size:13px;color:#8A8F98">${d}</div></div>`).join('');
  const list = rows.slice(0, 100).map((r, i) => `<div class="row"${i >= 50 ? ' hidden data-more="1"' : ''} data-b="${r.verified ? 'v' : ''}${r.rank <= 10 ? 't' : ''}${r.gain > 0 ? 'r' : ''}">${mark(r, 38)}<div class="m"><b><a href="/p/${esc(r.slug)}">${esc(r.name)}</a></b><p class="mono" style="font-size:11px">ranker.flisk.si/p/${esc(r.slug)}</p></div><img src="/badge/${esc(r.slug)}.svg" width="250" height="55" loading="lazy" alt=""><button type="button" onclick="navigator.clipboard.writeText('[![Flisk Ranker](${esc(origin)}/badge/${esc(r.slug)}.svg)](${esc(origin)}/p/${esc(r.slug)})');this.textContent='Copied'">Copy embed</button></div>`).join('');
  const sample = top || 'sample', E = embed(origin, sample);
  const filter = `const f={All:'',Verified:'v','Top 10':'t',Rising:'r'};document.querySelectorAll('[data-f]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-f]').forEach(x=>x.classList.toggle('on',x===b));document.querySelectorAll('.row[data-b]').forEach(r=>r.style.display=!f[b.dataset.f]||r.dataset.b.includes(f[b.dataset.f])?'':'none')});document.querySelectorAll('[data-th]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-th]').forEach(x=>x.classList.toggle('on',x===b));const d=document.getElementById('rd'),l=b.dataset.th==='l';d.style.background=l?'#fff':'#0D1117';d.querySelectorAll('div').forEach((e,i)=>e.style.color=l?(i?'#59636E':'#1F2328'):(i?'#9198A1':'#E6EDF3'))});const code=document.getElementById('gen'),V={md:${JSON.stringify(E.markdown)},html:${JSON.stringify(E.html)},url:${JSON.stringify(origin + '/badge/' + sample + '.svg')}};document.querySelectorAll('[data-g]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-g]').forEach(x=>x.classList.toggle('on',x===b));code.textContent=V[b.dataset.g]})`;
  const body = `<div class="hero"><div class="t"><div class="lbl">BADGES &middot; LIVE IMAGES FOR YOUR README</div><h1>Show your rank where people look.</h1><p class="sub">Every listed product gets live badges. They update by themselves, link back to your Ranker page, and nobody can buy a rank.</p><p style="margin-top:24px"><a class="btn p" href="/submit" style="padding:12px 20px">Get my badge, free</a> <a class="btn" href="#all" style="padding:12px 20px">Find my product</a></p></div></div>
<div style="border-top:1px solid #1E2229;padding-top:28px"><div class="lbl">THE BADGES</div><div class="grid" style="margin-top:18px"><div class="card" style="flex:1 1 300px"><img src="/badge/sample.svg" width="250" height="55" alt="Sample badge"><div style="font-size:15px;font-weight:500;margin:14px 0 4px">Large, 250 px</div><div style="font-size:13px;color:#8A8F98">Body by total stars, rank colour by position: 625 looks.</div></div><div class="card" style="flex:1 1 300px"><img src="/badge/sample.svg?size=small" height="20" alt=""><div style="font-size:15px;font-weight:500;margin:14px 0 4px">Small, 20 px</div><div style="font-size:13px;color:#8A8F98">For tight READMEs.</div></div>${gallery}</div></div>
<div class="cols" id="all"><div class="a"><div style="display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-bottom:12px"><span class="lbl">EVERY LISTED PRODUCT HAS ONE &middot; ${rows.length}</span><span style="flex:1"></span>${['All', 'Verified', 'Top 10', 'Rising'].map((n, i) => `<button type="button" class="pill ${i ? '' : 'on'}" data-f="${n}">${n}</button>`).join('')}</div>${list}${rows.length > 50 ? `<p style="margin-top:16px"><button type="button" class="btn" onclick="document.querySelectorAll('[data-more]').forEach(function(e){e.hidden=false});this.remove()">Show the next ${Math.min(50, rows.length - 50)} &#8594;</button></p>` : ''}</div>
<div class="b"><div class="card"><div class="lbl">COPY THIS INTO YOUR README</div><div style="display:flex;flex-wrap:wrap;gap:8px;margin:16px 0 4px"><button type="button" class="pill on" data-g="md">Markdown</button><button type="button" class="pill" data-g="html">HTML</button><button type="button" class="pill" data-g="url">URL</button></div><code id="gen">${esc(E.markdown)}</code><button type="button" onclick="navigator.clipboard.writeText(document.getElementById('gen').textContent);this.textContent='Copied'">Copy</button><p style="font-size:12px;line-height:1.6;color:#6B7079;margin:14px 0 0">Add ?period=weekly, monthly or yearly, or ?size=small. Finding it in your README marks your page verified.</p></div>
<div class="card" style="padding:0;overflow:hidden"><div style="display:flex;gap:8px;align-items:center;padding:14px 18px;border-bottom:1px solid #1E2229"><span class="lbl">HOW IT LOOKS IN A README</span><span style="flex:1"></span><button type="button" class="pill on" data-th="d">Dark</button><button type="button" class="pill" data-th="l">Light</button></div><div id="rd" style="background:#0D1117;padding:22px 20px"><div style="font-size:22px;font-weight:600;margin-bottom:12px;color:#E6EDF3">${esc(rows[0]?.name || 'Your product')}</div><img src="/badge/${esc(sample)}.svg" width="250" height="55" alt=""><div style="font-size:14px;line-height:1.6;color:#9198A1;margin-top:12px">${esc(rows[0]?.tagline || '')}</div></div></div>
<div class="card blue"><div class="lbl">WHY PUT IT THERE</div><div class="kv" style="margin-top:14px"><div>Every visitor to your README sees proof people use you.</div><div>Each click lands on your Ranker page and brings new visitors back to you.</div><div>It changes by itself. Rise in the ranking and the badge shows it.</div></div></div></div></div>`;
  return shell('Badges', body, { script: filter });
}

const gainTxt = (r) => (r.isNew ? 'Collecting' : (r.gain >= 0 ? '+' : '') + short(r.gain));
export const sampleBadge = (size) => badgeSvg({ rank: 1, stars: 40000, size });

const ago = (t) => { const m = Math.max(1, Math.round((Date.now() - t) / 6e4)); return m < 60 ? m + ' min ago' : m < 1440 ? Math.round(m / 60) + ' h ago' : Math.round(m / 1440) + ' d ago'; };
const LOGO = {
  'Hacker News': ['#FF6600', '<path d="M8 7l4 7.2L16 7M12 14.2V19" fill="none" stroke="#fff" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/>'],
  Bluesky: ['#0085FF', '<path transform="translate(3.6 4.2) scale(.74)" fill="#fff" d="M12 10.8c-1.087-2.114-4.046-6.053-6.798-7.995C2.566.944 1.561 1.266.902 1.565.139 1.908 0 3.08 0 3.768c0 .69.378 5.65.624 6.479.815 2.736 3.713 3.66 6.383 3.364.136-.02.275-.039.415-.056-3.912.58-7.387 2.005-2.83 7.078 5.013 5.19 6.87-1.113 7.823-4.308.953 3.195 2.05 9.271 7.733 4.308 4.267-4.308 1.172-6.498-2.74-7.078.14.017.279.036.415.056 2.67.297 5.568-.628 6.383-3.364.246-.828.624-5.79.624-6.478 0-.69-.139-1.861-.902-2.206-.659-.298-1.664-.62-4.3 1.24C16.046 4.748 13.087 8.687 12 10.8Z"/>'],
  Reddit: ['#FF4500', '<ellipse cx="12" cy="14" rx="6.5" ry="4.6" fill="#fff"/><circle cx="6.4" cy="10.6" r="1.8" fill="#fff"/><circle cx="17.6" cy="10.6" r="1.8" fill="#fff"/><circle cx="9.7" cy="13.4" r="1.1" fill="#FF4500"/><circle cx="14.3" cy="13.4" r="1.1" fill="#FF4500"/><path d="M9.6 16.2c1.4 1 3.4 1 4.8 0M12 9.4l1.1-3.6 3 .7" fill="none" stroke="#FF4500" stroke-width="1.1" stroke-linecap="round"/><circle cx="17.4" cy="6.8" r="1.3" fill="#fff"/>'],
  X: ['#000', '<path d="M6.5 6.5l11 11M17.5 6.5l-11 11" stroke="#fff" stroke-width="2.2" stroke-linecap="round"/>'],
  YouTube: ['#FF0000', '<rect x="4" y="7" width="16" height="10.4" rx="3" fill="#fff"/><path d="M10.5 9.8v4.8l4.2-2.4z" fill="#FF0000"/>'],
};
export const srcLogo = (src, n = 36) => {
  const l = LOGO[src];
  return l
    ? `<svg role="img" aria-label="${esc(src)}" viewBox="0 0 24 24" width="${n}" height="${n}" style="flex:none;border-radius:50%;box-shadow:0 0 0 1px #2A2F38"><title>${esc(src)}</title><rect width="24" height="24" fill="${l[0]}"/>${l[1]}</svg>`
    : `<span class="pill" style="flex:none;height:fit-content">${esc(src)}</span>`;
};
const mrow = (m, who) => { const prod = who && typeof who === 'object' ? who : null; const name = prod ? prod.name : who; return `<div style="display:flex;gap:16px;padding:16px 0;border-top:1px solid #12151A">${srcLogo(m.source)}<div style="flex:1;min-width:0">${name ? `<div style="display:flex;align-items:center;gap:8px;margin-bottom:4px">${prod ? mark(prod, 22) : ''}<b style="font-weight:500">${esc(name)}</b></div>` : ''}<a href="${esc(m.url)}" rel="nofollow noopener" style="font-size:15px;line-height:1.45;color:#D5D8DD">${esc(m.text.slice(0, 220))}</a><div class="mono" style="font-size:11px;color:#6B7079;margin-top:6px">${esc(m.author)} &middot; ${esc(m.source)}</div></div><div class="mono" style="font-size:11px;color:#6B7079;flex:none">${ago(m.at)}</div></div>`; };
const SRC = { hn: 'Hacker News', bluesky: 'Bluesky', x: 'X', reddit: 'Reddit', youtube: 'YouTube' };
const SOON = '<span class="pill soon">Coming soon</span>';
const soonBox = (label, text) => `<div class="card"><div class="lbl">${label}</div><p style="margin:10px 0 0;font-size:14px;color:#9AA0AA">${text || 'Coming soon.'}</p></div>`;

// Compare up to four products side by side: real numbers where we have them, "Coming soon" where we do not.
export function compare(rows, snaps, all, facts = {}, ments = []) {
  const cols = rows.slice(0, 4);
  const names = cols.map((c) => esc(c.name)).join(' vs ');
  const opts = all.filter((r) => !cols.find((c) => c.slug === r.slug)).slice(0, 100).map((r) => `<option value="${esc(r.slug)}">${esc(r.name)}</option>`).join('');
  const rm = (c) => `/compare?p=${esc(cols.filter((x) => x.slug !== c.slug).map((x) => x.slug).join(','))}`;
  const best = (f) => { const v = cols.map(f); const m = Math.max(...v); return v.map((x) => (x === m && v.filter((y) => y === m).length === 1 ? '#5BE49B' : '#D5D8DD')); };
  const sc = best((c) => c.stars), gc = best((c) => c.gain), kc = best((c) => -c.rank);
  const cell = (c, i, w = 760) => `<div style="flex:1;padding:18px 24px;border-left:1px solid #1E2229;font-size:15px;color:${c}">${i}</div>`;
  const line = (l, vals, colors) => `<div style="display:flex;border-bottom:1px solid #12151A"><div class="lbl" style="flex:0 0 200px;padding:18px 24px">${l}</div>${vals.map((v, i) => cell(colors ? colors[i] : '#D5D8DD', v)).join('')}</div>`;
  const spark = (c) => { const v = starsOf(snaps, c.slug, 90); return v.length > 1 ? line0(v) : '<small>Not enough days yet</small>'; };
  const line0 = (v) => { const lo = Math.min(...v), hi = Math.max(...v), span = hi - lo || 1; const pts = v.map((x, i) => `${Math.round((i / (v.length - 1)) * 160)},${Math.round(42 - ((x - lo) / span) * 40)}`).join(' '); return `<svg viewBox="0 0 160 44" aria-hidden="true" style="width:100%;height:44px"><polyline points="${pts}" fill="none" stroke="#5BE49B" stroke-width="2"/></svg>`; };
  let verdict = '';
  if (cols.length > 1) {
    const fast = [...cols].sort((a, b) => b.gain - a.gain)[0], old = [...cols].sort((a, b) => b.stars - a.stars)[0];
    verdict = `<div class="card blue" style="display:flex;flex-wrap:wrap;gap:28px;align-items:center;margin-bottom:24px"><div style="flex:1 1 380px"><div class="lbl">THE VERDICT</div><div style="font-size:22px;line-height:1.4;font-weight:300;margin-top:8px">${fast.slug === old.slug ? `${esc(fast.name)} is both rising fastest today and the most established.` : `${esc(fast.name)} is rising fastest today. ${esc(old.name)} is the most established.`}</div></div><div style="flex:0 0 260px;display:flex;flex-direction:column;gap:8px;font-size:14px"><div><span class="lbl">FASTEST RISING</span><br>${esc(fast.name)}, ${fast.gain >= 0 ? '+' : ''}${short(fast.gain)} stars today</div><div><span class="lbl">MOST ESTABLISHED</span><br>${esc(old.name)}, ${short(old.stars)} stars</div><div><span class="lbl">LOWEST PRICE</span><br>${SOON}</div></div></div>`;
  }
  const soonRow = (l) => line(l, cols.map(() => SOON));
  const table = cols.length
    ? `${verdict}<div class="card" style="padding:0;overflow-x:auto"><div style="min-width:${200 + cols.length * 200}px"><div style="display:flex;border-bottom:1px solid #1E2229"><div style="flex:0 0 200px;padding:22px 24px"></div>${cols.map((c) => `<div style="flex:1;padding:22px 24px;border-left:1px solid #1E2229"><div style="display:flex;gap:12px;align-items:center">${mark(c, 42)}<div><div style="font-size:18px;font-weight:500">${esc(c.name)}</div><div class="mono" style="font-size:11px;color:${c.verified ? '#5BE49B' : '#6B7079'}">${c.verified ? '&#10003; VERIFIED' : 'NOT VERIFIED YET'}</div></div></div><div style="margin-top:14px"><a class="btn" href="/p/${esc(c.slug)}" style="font-size:12px;padding:7px 11px">Open page</a> <a class="btn" href="${rm(c)}" style="font-size:12px;padding:7px 11px">Remove</a></div></div>`).join('')}</div>
${line('TRENDING RANK', cols.map((c) => '#' + c.rank + ' today'), kc)}${line('STARS', cols.map((c) => short(c.stars)), sc)}${line('STARS TODAY', cols.map(gainTxt), gc)}${line('MERGED PRS &middot; 30 DAYS', cols.map((c) => facts[c.slug]?.prs ?? SOON))}${line('LAST RELEASE', cols.map((c) => { const l = facts[c.slug]?.last; return l ? esc(l.tag) + ' &middot; ' + ago(l.at) : SOON; }))}${line('LICENCE', cols.map((c) => esc(c.license || 'None listed')))}${line('LANGUAGE', cols.map((c) => esc(c.language || '-')))}${soonRow('PRICE TO START')}${soonRow('PAID PLAN')}${soonRow('PRICE CHECKED')}${line('MENTIONS &middot; 30 DAYS', cols.map((c) => String(ments.filter((m) => m.slug === c.slug).length)))}
<div style="display:flex"><div class="lbl" style="flex:0 0 200px;padding:18px 24px">STARS, 90 DAYS</div>${cols.map((c) => `<div style="flex:1;padding:14px 24px;border-left:1px solid #1E2229">${spark(c)}</div>`).join('')}</div></div></div>`
    : '<p class="sub">Pick two to four products below.</p>';
  const add = cols.length < 4 && opts ? `<form method="get" action="/compare" class="card" style="margin-top:20px"><input type="hidden" name="p" value="${esc(cols.map((c) => c.slug).join(','))}"><div class="lbl">+ ADD A PRODUCT</div><select style="margin:10px 0">${opts}</select><button type="submit" onclick="var f=this.form,h=f.p;h.value=(h.value?h.value+',':'')+f.querySelector('select').value">Add</button></form>` : '';
  const pairs = []; for (let a = 0; a < Math.min(all.length, 4); a++) for (let b = a + 1; b < Math.min(all.length, 4); b++) pairs.push([all[a], all[b]]);
  const others = pairs.slice(0, 5).map(([a, b]) => `<a href="/compare?p=${esc(a.slug)},${esc(b.slug)}" style="display:flex;align-items:center;padding:14px 0;border-top:1px solid #12151A;margin-top:12px;font-size:15px"><span style="display:flex;align-items:center;gap:8px;flex:1">${mark(a, 22)}${esc(a.name)} vs ${mark(b, 22)}${esc(b.name)}</span><span class="mono" style="font-size:11px;color:#6B7079">Compare</span></a>`).join('') || '<p style="font-size:14px;color:#9AA0AA">More comparisons appear as products join.</p>';
  const body = `<div class="hero"><div class="t"><div class="lbl">COMPARE</div><h1>${names || 'Compare products'}</h1><p class="sub">Same numbers for every product: live GitHub activity, price with its checked date, and what people say. Add up to four.</p><div style="display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin-top:22px">${cols.map((c) => `<a class="pill" style="color:#fff;display:inline-flex;align-items:center;gap:7px" href="${rm(c)}">${mark(c, 18)}${esc(c.name)} &times;</a>`).join('')}<a class="pill" style="border-style:dashed" href="#add">+ Add a product</a></div></div></div>${table}<div id="add">${add}</div>
<div style="display:flex;flex-wrap:wrap;gap:24px;margin-top:24px"><div class="card" style="flex:1 1 420px"><div class="lbl">WHAT PEOPLE SAY &middot; VIA FLISK GROW</div>${(() => { const ms = ments.filter((m) => cols.some((c) => c.slug === m.slug)).slice(0, 5); return ms.length ? ms.map((m) => mrow(m, cols.find((c) => c.slug === m.slug))).join('') : `<p style="margin:12px 0 0;color:#9AA0AA;font-size:14px">${SOON}</p>`; })()}</div><div class="card" style="flex:1 1 420px"><div class="lbl">OTHER COMPARISONS</div>${others}<div class="spon" style="margin-top:18px"><div class="lbl">FEATURED</div><p style="margin:8px 0 0">Sponsor slot: shown apart from the verdict. It never changes a verdict.</p></div></div></div>`;
  return shell('Compare products', body);
}

// Live mentions need Flisk Grow. The page has its whole design; every part that needs Grow says "Coming soon".
export function live(rows = [], ments = []) {
  const cnt = {}; for (const m of ments) cnt[m.slug] = (cnt[m.slug] || 0) + 1;
  const bySrc = {}; for (const m of ments) bySrc[m.source] = (bySrc[m.source] || 0) + 1;
  const KEY = { 'Hacker News': 'hn', Bluesky: 'bluesky' };
  const srcs = ['All sources', 'X', 'Hacker News', 'Reddit', 'Bluesky', 'YouTube'].map((n, i) => `<span ${KEY[n] ? `data-src="${KEY[n]}" role="button" ` : i === 0 ? 'data-src="" role="button" ' : ''}class="pill ${i === 0 ? 'on' : ['X', 'Reddit', 'YouTube'].includes(n) ? 'soon' : ''}" style="display:inline-flex;align-items:center;gap:7px;cursor:${i === 0 || KEY[n] ? 'pointer' : 'default'}">${i === 0 ? '' : srcLogo(n, 16)}${n}${['X', 'Reddit', 'YouTube'].includes(n) ? ': soon' : ''}</span>`).join('');
  const nm = (slug) => rows.find((r) => r.slug === slug)?.name || slug;
  const hot = rows.filter((r) => cnt[r.slug]).sort((a, b) => cnt[b.slug] - cnt[a.slug]).slice(0, 5).map((r, i) => `<div style="display:flex;align-items:center;gap:12px;padding:12px 0;border-top:1px solid #12151A;margin-top:10px"><span class="mono" style="width:22px;font-size:13px;color:#6B7079">0${i + 1}</span>${mark(r, 24)}<a href="/p/${esc(r.slug)}" style="flex:1;font-size:14px;font-weight:500">${esc(r.name)}</a><span class="mono" style="font-size:12px;color:#6B7079">${cnt[r.slug]} mentions</span></div>`).join('');
  const top = Math.max(1, ...Object.values(bySrc));
  const bars = ['X', 'Reddit', 'Hacker News', 'Bluesky', 'YouTube'].map((n) => `<div style="margin-top:14px"><div style="display:flex;justify-content:space-between;font-size:13px;margin-bottom:6px"><span style="display:flex;align-items:center;gap:8px">${srcLogo(n, 18)}${n}</span><span class="mono" style="color:#8A8F98">${bySrc[n] ?? 'soon'}</span></div><div style="height:6px;border-radius:3px;background:#12151A"><div style="height:6px;border-radius:3px;background:#5BE49B;width:${Math.round(((bySrc[n] || 0) / top) * 100)}%"></div></div></div>`).join('');
  const body = `<div class="hero"><div class="t"><div style="display:flex;align-items:center;gap:10px"><span style="width:9px;height:9px;border-radius:50%;background:#5BE49B;box-shadow:0 0 0 4px rgba(91,228,155,.18)"></span><span class="lbl">LIVE &middot; HACKER NEWS AND BLUESKY &middot; X, REDDIT, YOUTUBE COMING SOON</span></div><h1>Who is talking about what, right now.</h1><p class="sub">Every mention of every listed product on X, Hacker News, Reddit, Bluesky and YouTube, found by Flisk Grow and matched to the right product.</p></div><canvas id="globe" aria-hidden="true"></canvas></div>
<div style="display:flex;flex-wrap:wrap;gap:12px;align-items:center;padding:18px 0;border-top:1px solid #1E2229;border-bottom:1px solid #1E2229">${srcs}<span style="flex:1"></span><select id="fp" aria-label="Product" class="pill"><option value="">All products</option>${[...new Set(ments.map((m) => m.slug))].map((sl) => `<option value="${esc(sl)}">${esc(nm(sl))}</option>`).join('')}</select><select id="ft" aria-label="Time" class="pill"><option value="0">Last 30 days</option><option value="3600000">Last hour</option><option value="86400000">Last day</option><option value="604800000">Last week</option></select></div>
<div class="cols"><div class="a"><div class="card"><div class="lbl">THE FEED &middot; ${ments.length} IN 30 DAYS</div>${ments.slice(0, 200).map((m, i) => `<div data-m data-s="${esc(m.source)}" data-p="${esc(m.slug)}" data-at="${Number(m.at) || 0}"${i >= 40 ? ' data-more="1" hidden' : ''}>${mrow(m, rows.find((r) => r.slug === m.slug) || nm(m.slug))}</div>`).join('') || '<p style="margin:12px 0 0;font-size:14px;color:#9AA0AA">No mentions found yet. We look for each product every hour.</p>'}${ments.length > 40 ? `<p style="margin:14px 0 0"><button type="button" class="btn" onclick="document.querySelectorAll('[data-more]').forEach(function(e){e.hidden=false});this.remove()">Load ${Math.min(50, ments.length - 40)} more &#8594;</button></p>` : ''}<p style="margin:14px 0 0;font-size:13px;color:#6B7079">Likes, and whether a post is positive or a question: coming soon.</p></div></div>
<div class="b"><div class="card"><div class="lbl">MOST TALKED ABOUT &middot; 30 DAYS</div>${hot || `<p style="margin:10px 0 0">${SOON}</p>`}</div><div class="card"><div class="lbl">BY SOURCE &middot; 30 DAYS</div>${bars}</div><div class="card blue"><div class="lbl">FOR MAKERS</div><p style="margin:10px 0 14px;font-size:14px;color:#B8BDC6">Get an email the minute someone mentions your product, with a link to reply.</p><a class="btn p" href="/submit">Submit your product</a></div><div class="spon"><div class="lbl">FEATURED</div><p style="margin:8px 0 0">Sponsor slot: marked and kept apart from the feed.</p></div></div></div>`;
  return shell('Live mentions', body, { script: GLOBE + ';' + LIVEF });
}
